<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap/app.php';
$user=pf_require_login($pdo);$error='';$notice='';
$q=$pdo->prepare('SELECT p.advertiser_name,p.contact_email,p.website,p.description,p.status,m.can_advertise FROM pf_advertiser_profiles p JOIN pf_account_modes m ON m.user_id=p.user_id WHERE p.user_id=? LIMIT 1');$q->execute([(int)$user['id']]);$profile=$q->fetch();
if(!$profile||(int)$profile['can_advertise']!==1||!pf_legacy_advertiser_access_allowed($pdo,(int)$user['id'])){http_response_code(403);exit('Advertiser profile editing is not available for this account.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 pf_verify_csrf();$name=trim((string)($_POST['advertiser_name']??''));$email=strtolower(trim((string)($_POST['contact_email']??'')));$website=trim((string)($_POST['website']??''));$description=trim((string)($_POST['description']??''));$parts=$website!==''?parse_url($website):[];
 if(strlen($name)<2||strlen($name)>150||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190||strlen($description)>1200||($website!==''&&(!filter_var($website,FILTER_VALIDATE_URL)||strtolower((string)($parts['scheme']??''))!=='https'||empty($parts['host'])||strlen($website)>500)))$error='Enter a business name, valid contact email, optional HTTPS website and a description under 1,200 characters.';
 else{$pdo->prepare('UPDATE pf_advertiser_profiles SET advertiser_name=?,contact_email=?,website=?,description=? WHERE user_id=?')->execute([$name,$email,$website?:null,$description?:null,(int)$user['id']]);$profile['advertiser_name']=$name;$profile['contact_email']=$email;$profile['website']=$website;$profile['description']=$description;$notice='Your advertiser profile has been saved. Profile status is controlled by PoketFlow administrators.';}
}
?>
